CREATE TABLE provider_account_claims(claim_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),provider TEXT NOT NULL CHECK(provider IN('openai','anthropic','openrouter','oss')),account_reference TEXT NOT NULL,account_owner_reference TEXT NOT NULL,claimant_id TEXT NOT NULL,evidence_references_json TEXT NOT NULL,effective_at TEXT NOT NULL,expires_at TEXT,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE provider_verification_decisions(decision_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),evidence_id TEXT NOT NULL,verifier_id TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN('VERIFIED','REJECTED')),reason_codes_json TEXT NOT NULL,decided_at TEXT NOT NULL,valid_until TEXT,correlation_id TEXT NOT NULL);
CREATE TABLE provider_account_identities(provider_account_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),canonical_key TEXT NOT NULL UNIQUE,provider TEXT NOT NULL,account_reference TEXT NOT NULL,account_owner_reference TEXT NOT NULL,adapter_identity TEXT NOT NULL,environment_class TEXT NOT NULL,effective_at TEXT NOT NULL,verified_at TEXT NOT NULL,reverify_at TEXT,claim_id TEXT NOT NULL UNIQUE REFERENCES provider_account_claims(claim_id),decision_id TEXT NOT NULL UNIQUE REFERENCES provider_verification_decisions(decision_id),correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE provider_deployment_identities(provider_deployment_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),provider_account_id TEXT NOT NULL REFERENCES provider_account_identities(provider_account_id),deployment_reference TEXT NOT NULL,deployment_class TEXT NOT NULL,model_references_json TEXT NOT NULL,processing_service_identity TEXT NOT NULL,verified_regions_json TEXT NOT NULL,credential_reference TEXT,effective_at TEXT NOT NULL,evidence_references_json TEXT NOT NULL,verified_at TEXT NOT NULL,reverify_at TEXT,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,UNIQUE(provider_account_id,deployment_reference));
CREATE TABLE provider_credential_bindings(binding_id TEXT PRIMARY KEY,provider_account_id TEXT NOT NULL REFERENCES provider_account_identities(provider_account_id),provider_deployment_id TEXT REFERENCES provider_deployment_identities(provider_deployment_id),credential_reference TEXT NOT NULL,bound_at TEXT NOT NULL,evidence_reference TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,UNIQUE(provider_account_id,provider_deployment_id,credential_reference));
CREATE TABLE provider_attestation_evidence(evidence_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),issuer_id TEXT NOT NULL,issuer_class TEXT NOT NULL,provider_account_id TEXT NOT NULL,provider_deployment_id TEXT,subject TEXT NOT NULL,value_json TEXT NOT NULL,evidence_type TEXT NOT NULL,governed_reference TEXT NOT NULL,immutable_digest TEXT NOT NULL,effective_at TEXT NOT NULL,expires_at TEXT,verification_state TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE provider_contractual_attestations(attestation_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),provider_account_id TEXT NOT NULL REFERENCES provider_account_identities(provider_account_id),provider_deployment_id TEXT,subject TEXT NOT NULL,value_json TEXT NOT NULL,evidence_id TEXT NOT NULL REFERENCES provider_attestation_evidence(evidence_id),issuer_id TEXT NOT NULL,issuer_class TEXT NOT NULL,effective_at TEXT NOT NULL,expires_at TEXT,verified_at TEXT NOT NULL,decision_id TEXT NOT NULL,correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE provider_attestation_sets(provider_account_id TEXT PRIMARY KEY REFERENCES provider_account_identities(provider_account_id),attestation_set_digest TEXT NOT NULL,attestation_ids_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE provider_attestation_transitions(transition_id TEXT PRIMARY KEY,subject_id TEXT NOT NULL,subject_kind TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('EXPIRED','REVOKED','SUPERSEDED','CONTRADICTED')),reference TEXT NOT NULL UNIQUE,transitioned_at TEXT NOT NULL,correlation_id TEXT NOT NULL);
CREATE TABLE provider_attestation_audit_events(audit_event_id TEXT PRIMARY KEY,event_type TEXT NOT NULL,subject_id TEXT NOT NULL,outcome TEXT NOT NULL,correlation_id TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE UNIQUE INDEX provider_attestation_active_subject ON provider_contractual_attestations(provider_account_id,COALESCE(provider_deployment_id,''),subject,value_json);
CREATE TRIGGER provider_claim_immutable BEFORE UPDATE ON provider_account_claims BEGIN SELECT RAISE(ABORT,'PROVIDER_CLAIM_IMMUTABLE');END;
CREATE TRIGGER provider_claim_no_delete BEFORE DELETE ON provider_account_claims BEGIN SELECT RAISE(ABORT,'PROVIDER_CLAIM_IMMUTABLE');END;
CREATE TRIGGER provider_decision_immutable BEFORE UPDATE ON provider_verification_decisions BEGIN SELECT RAISE(ABORT,'PROVIDER_DECISION_IMMUTABLE');END;
CREATE TRIGGER provider_decision_no_delete BEFORE DELETE ON provider_verification_decisions BEGIN SELECT RAISE(ABORT,'PROVIDER_DECISION_IMMUTABLE');END;
CREATE TRIGGER provider_account_immutable BEFORE UPDATE ON provider_account_identities BEGIN SELECT RAISE(ABORT,'PROVIDER_ACCOUNT_IMMUTABLE');END;
CREATE TRIGGER provider_account_no_delete BEFORE DELETE ON provider_account_identities BEGIN SELECT RAISE(ABORT,'PROVIDER_ACCOUNT_IMMUTABLE');END;
CREATE TRIGGER provider_deployment_immutable BEFORE UPDATE ON provider_deployment_identities BEGIN SELECT RAISE(ABORT,'PROVIDER_DEPLOYMENT_IMMUTABLE');END;
CREATE TRIGGER provider_deployment_no_delete BEFORE DELETE ON provider_deployment_identities BEGIN SELECT RAISE(ABORT,'PROVIDER_DEPLOYMENT_IMMUTABLE');END;
CREATE TRIGGER provider_credential_immutable BEFORE UPDATE ON provider_credential_bindings BEGIN SELECT RAISE(ABORT,'PROVIDER_CREDENTIAL_IMMUTABLE');END;
CREATE TRIGGER provider_credential_no_delete BEFORE DELETE ON provider_credential_bindings BEGIN SELECT RAISE(ABORT,'PROVIDER_CREDENTIAL_IMMUTABLE');END;
CREATE TRIGGER provider_evidence_immutable BEFORE UPDATE ON provider_attestation_evidence BEGIN SELECT RAISE(ABORT,'PROVIDER_EVIDENCE_IMMUTABLE');END;
CREATE TRIGGER provider_evidence_no_delete BEFORE DELETE ON provider_attestation_evidence BEGIN SELECT RAISE(ABORT,'PROVIDER_EVIDENCE_IMMUTABLE');END;
CREATE TRIGGER provider_attestation_immutable BEFORE UPDATE ON provider_contractual_attestations BEGIN SELECT RAISE(ABORT,'PROVIDER_ATTESTATION_IMMUTABLE');END;
CREATE TRIGGER provider_attestation_no_delete BEFORE DELETE ON provider_contractual_attestations BEGIN SELECT RAISE(ABORT,'PROVIDER_ATTESTATION_IMMUTABLE');END;
CREATE TRIGGER provider_set_immutable BEFORE UPDATE ON provider_attestation_sets BEGIN SELECT RAISE(ABORT,'PROVIDER_SET_IMMUTABLE');END;
CREATE TRIGGER provider_set_no_delete BEFORE DELETE ON provider_attestation_sets BEGIN SELECT RAISE(ABORT,'PROVIDER_SET_IMMUTABLE');END;
CREATE TRIGGER provider_transition_immutable BEFORE UPDATE ON provider_attestation_transitions BEGIN SELECT RAISE(ABORT,'PROVIDER_TRANSITION_IMMUTABLE');END;
CREATE TRIGGER provider_transition_no_delete BEFORE DELETE ON provider_attestation_transitions BEGIN SELECT RAISE(ABORT,'PROVIDER_TRANSITION_IMMUTABLE');END;
CREATE TRIGGER provider_audit_immutable BEFORE UPDATE ON provider_attestation_audit_events BEGIN SELECT RAISE(ABORT,'PROVIDER_AUDIT_IMMUTABLE');END;
CREATE TRIGGER provider_audit_no_delete BEFORE DELETE ON provider_attestation_audit_events BEGIN SELECT RAISE(ABORT,'PROVIDER_AUDIT_IMMUTABLE');END;
